definition.script:
import groovy.json.JsonSlurper;

def targetStack
def infrastructureGitHash
def rotationRendered = false
def psamaUploaded = false
def wildflyDeployed = false
def loggingDeployed = false
def hpdsAuthDeployed = false

pipeline {
    agent any

    environment {
        SOURCE_SCRIPTS_FOLDER = "${JENKINS_HOME}/workspace/Bash_Functions/"
    }

    stages {
        stage('Validate Selection') {
            steps {
                script {
                    if (!params.ROTATE_STACK_SECRETS && !params.ROTATE_LOGGING_API_KEY && !params.ROTATE_PICSURE_INTERNAL_TOKEN) {
                        error("None of ROTATE_STACK_SECRETS, ROTATE_LOGGING_API_KEY and ROTATE_PICSURE_INTERNAL_TOKEN is true, so this run would mint nothing. Set at least one.")
                    }
                    if (params.ROTATE_PICSURE_INTERNAL_TOKEN && (!params.DATA_S3_OBJECT_KEY?.trim() || !params.GENOMIC_DATASET_S3_OBJECT_KEY?.trim())) {
                        error("ROTATE_PICSURE_INTERNAL_TOKEN redeploys auth HPDS, and DATA_S3_OBJECT_KEY or GENOMIC_DATASET_S3_OBJECT_KEY is empty. With an empty key the host falls back to the dataset it was provisioned with, so a stack whose data was deployed since then would be rolled back to the old dataset. Nothing was minted or rendered. Set both to the keys the stack serves now: the parameters of the last successful PIC-SURE HPDS Auth Deploy build for this stack, or, when there has been none since the stack was built, the dataset keys of the Deployment Pipeline run that built it. /opt/picsure/deploy-script-last-execution-values.txt on the auth HPDS host records the same two values.")
                    }
                }
            }
        }

        stage('Retrieve Stack') {
            steps {
                script {
                    targetStack = sh(script: """
                    bash -c '
                    set +x

                    if [ ! -d "$SOURCE_SCRIPTS_FOLDER" ]; then
                        echo "Error: Source folder does not exist: $SOURCE_SCRIPTS_FOLDER"
                        exit 1
                    fi

                    for script_file in "$SOURCE_SCRIPTS_FOLDER"*.sh; do
                        chmod +x "\$script_file"
                        if [ -f "\$script_file" ] && [ -x "\$script_file" ]; then
                            . "\$script_file"
                        fi
                    done

                    get_stack \"${TARGET_STACK}\"
                    '
                    """, returnStdout: true).trim()

                    println "TARGET_STACK: $targetStack"
                }
            }
        }

        stage('Resolve Infrastructure Git Hash') {
            steps {
                script {
                    if (params.INFRASTRUCTURE_GIT_HASH?.trim()) {
                        infrastructureGitHash = params.INFRASTRUCTURE_GIT_HASH.trim()
                        echo "Using provided INFRASTRUCTURE_GIT_HASH: ${infrastructureGitHash}"
                    } else {
                        def result = build job: 'Retrieve Build Spec'
                        copyArtifacts filter: 'build-spec.json', projectName: 'Retrieve Build Spec', selector: specific("" + result.number)
                        def buildSpec = new JsonSlurper().parse(new File("${env.WORKSPACE}/build-spec.json"))
                        infrastructureGitHash = buildSpec.infrastructure_git_hash
                        echo "Resolved INFRASTRUCTURE_GIT_HASH from release control: ${infrastructureGitHash}"
                    }
                }
            }
        }

        stage('Rotate and Redeploy') {
            steps {
                script {
                    // The gateway carries the stack secrets and the logging key, so either one pulls it in.
                    // PICSURE_INTERNAL_TOKEN lives only in the dictionary and auth HPDS env files.
                    def rotateStack = params.ROTATE_STACK_SECRETS
                    def rotateLogging = params.ROTATE_LOGGING_API_KEY
                    def rotateInternalToken = params.ROTATE_PICSURE_INTERNAL_TOKEN
                    def rotateGateway = rotateStack || rotateLogging

                    echo "Rotating on stack ${targetStack}: stack secrets=${rotateStack}, logging api key=${rotateLogging}, picsure internal token=${rotateInternalToken}"

                    lock("stack-${targetStack}") {
                        build job: 'Render PIC-SURE Configuration', parameters: [
                            [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                            [$class: 'StringParameterValue', name: 'INFRASTRUCTURE_GIT_HASH', value: infrastructureGitHash],
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                            [$class: 'BooleanParameterValue', name: 'RENDER_GATEWAY', value: rotateGateway],
                            [$class: 'BooleanParameterValue', name: 'RENDER_OPERATIONS', value: rotateStack || rotateLogging],
                            [$class: 'BooleanParameterValue', name: 'RENDER_QUERY', value: rotateStack],
                            [$class: 'BooleanParameterValue', name: 'RENDER_AUTH_HPDS', value: rotateInternalToken],
                            [$class: 'BooleanParameterValue', name: 'RENDER_OPEN_HPDS', value: false],
                            [$class: 'BooleanParameterValue', name: 'RENDER_VISUALIZATION', value: rotateLogging],
                            [$class: 'BooleanParameterValue', name: 'RENDER_LOGGING', value: rotateLogging],
                            [$class: 'BooleanParameterValue', name: 'RENDER_DICTIONARY', value: rotateLogging || rotateInternalToken],
                            [$class: 'BooleanParameterValue', name: 'ROTATE_STACK_SECRETS', value: rotateStack],
                            [$class: 'BooleanParameterValue', name: 'ROTATE_LOGGING_API_KEY', value: rotateLogging],
                            [$class: 'BooleanParameterValue', name: 'ROTATE_PICSURE_INTERNAL_TOKEN', value: rotateInternalToken]
                        ]
                        rotationRendered = true

                        if (rotateLogging) {
                            build job: 'Upload PSAMA Configuration', parameters: [
                                [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                                [$class: 'BooleanParameterValue', name: 'REFRESH_LOGGING_KEY', value: true]
                            ]
                            psamaUploaded = true
                        }
                        build job: 'PIC-SURE Wildfly Stack Deploy', parameters: [
                            [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_GATEWAY', value: rotateGateway],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_OPERATIONS', value: rotateStack || rotateLogging],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_QUERY', value: rotateStack],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_PSAMA', value: rotateLogging],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_DICTIONARY', value: rotateLogging || rotateInternalToken],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_VISUALIZATION', value: rotateLogging]
                        ]
                        wildflyDeployed = true

                        if (rotateLogging) {
                            build job: 'PIC-SURE Logging Deploy', parameters: [
                                [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                                [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack]
                            ]
                            loggingDeployed = true

                            echo "LOGGING_API_KEY was rotated for every stack. Render and redeploy gateway, operations and visualization on each other stack, and update every stack's configs/pic-sure-frontend/<stack>/bdc.env and redeploy its frontend, or their audit events are dropped."
                        }

                        if (rotateInternalToken) {
                            build job: 'PIC-SURE HPDS Auth Deploy', parameters: [
                                [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                                [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                                [$class: 'StringParameterValue', name: 'DATA_S3_OBJECT_KEY', value: params.DATA_S3_OBJECT_KEY.trim()],
                                [$class: 'StringParameterValue', name: 'GENOMIC_DATASET_S3_OBJECT_KEY', value: params.GENOMIC_DATASET_S3_OBJECT_KEY.trim()]
                            ]
                            hpdsAuthDeployed = true

                            echo "PICSURE_INTERNAL_TOKEN was rotated in the dictionary env that every stack shares, and stack ${targetStack} now runs on it. On each other stack, run Render PIC-SURE Configuration with RENDER_AUTH_HPDS and ADOPT_PICSURE_INTERNAL_TOKEN true, then PIC-SURE Dictionary Deploy and PIC-SURE HPDS Auth Deploy together. Until then that stack keeps the old value in both containers, redeploying only one of the two ends its PFB exports in ERROR, and every render there that includes the dictionary or auth HPDS aborts."
                        }
                    }
                }
            }
        }
    }

    post {
        always {
            script {
                if (rotationRendered) {
                    def rotateStack = params.ROTATE_STACK_SECRETS
                    def rotateLogging = params.ROTATE_LOGGING_API_KEY
                    def rotateInternalToken = params.ROTATE_PICSURE_INTERNAL_TOKEN
                    def owed = ''
                    if (rotateLogging && !psamaUploaded) {
                        owed += ' Upload PSAMA Configuration with REFRESH_LOGGING_KEY true.'
                    }
                    if (!wildflyDeployed) {
                        def deployFlags = ''
                        if (rotateStack || rotateLogging) {
                            deployFlags += ' DEPLOY_GATEWAY DEPLOY_OPERATIONS'
                        }
                        if (rotateStack) {
                            deployFlags += ' DEPLOY_QUERY'
                        }
                        if (rotateLogging) {
                            deployFlags += ' DEPLOY_PSAMA DEPLOY_VISUALIZATION'
                        }
                        if (rotateLogging || rotateInternalToken) {
                            deployFlags += ' DEPLOY_DICTIONARY'
                        }
                        owed += " PIC-SURE Wildfly Stack Deploy for stack ${targetStack} with exactly these flags true:${deployFlags}."
                    }
                    if (rotateLogging && !loggingDeployed) {
                        owed += " PIC-SURE Logging Deploy for stack ${targetStack}."
                    }
                    if (rotateInternalToken && !hpdsAuthDeployed) {
                        owed += " PIC-SURE HPDS Auth Deploy for stack ${targetStack} with the same DATA_S3_OBJECT_KEY and GENOMIC_DATASET_S3_OBJECT_KEY."
                    }
                    if (owed) {
                        echo "The rotated values were already rendered to S3 for stack ${targetStack} when this run stopped, and its env files agree with each other. Do not run this rotation again: a rerun mints new values on top of these. Finish by hand instead, in this order:${owed} Then do the follow-ups the job description lists for the other stacks."
                    }
                }
            }
        }
    }
}
